const fs = require('fs');

const [a, b, p, x] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

function modPow(base, exp, mod) {
    let result = 1;
    while (exp > 0) {
        if (exp % 2 === 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp = Math.floor(exp / 2);
    }
    return result;
}

const m = p - 1;
const period = p * m;
const invA = modPow(a, p - 2, p);

let invPow = 1;
let answer = 0;

for (let k = 0; k < m; k++) {
    const r = (b * invPow) % p;
    let t = (k - r) % p;
    if (t < 0) t += p;

    const first = k + m * t;

    if (first <= x) {
        answer += Math.floor((x - first) / period) + 1;
    }

    invPow = (invPow * invA) % p;
}

console.log(answer.toString());

